# area: final_classvar
# hypothesis: A frozen dataclass Final field is enforced at runtime, while a Final class attribute, a ClassVar written through an instance, and subclassing a @final class are only rejected by the checker.
from dataclasses import dataclass
from typing import ClassVar, Final, final, reveal_type


@final
class Counter:
    count: ClassVar[int] = 0
    step: Final[int] = 2

    def bump(self) -> int:
        Counter.count += self.step
        return Counter.count


class Sub(Counter):  # expect-error: cannot inherit from final class
    pass


@dataclass(frozen=True)
class Point:
    x: Final[int]
    y: int = 0


def write_point(p: Point) -> None:
    p.x = 5  # expect-error: assignment to Final field of frozen dataclass


def write_class_var(c: Counter) -> None:
    c.count = 3  # expect-error: ClassVar assigned through an instance


def write_final_attr() -> None:
    Counter.step = 3  # expect-error: Final attribute reassigned


c = Counter()
reveal_type(c.bump())
print(c.bump(), Counter.count)
print(type(Sub()).__name__)
p = Point(1)
reveal_type(p.x)
try:
    write_point(p)
except (AttributeError, TypeError) as exc:
    print('point:', type(exc).__name__)
write_class_var(c)
print(Counter.count, c.count)
try:
    write_final_attr()
except (AttributeError, TypeError) as exc:
    print('final:', type(exc).__name__)
